          remainder_re_ast, &re_ast, &remainder_re_ast, &min_gap, &max_gap);

      if (result != ERROR_SUCCESS)
        goto _exit;

      prev_string = aux_string;

      result = _yr_parser_write_string(
          identifier,
          string_flags,
          compiler,
          NULL,
          re_ast,
          &aux_string,
          &min_atom_quality_aux,
          &compiler->current_rule->num_atoms);

      if (result != ERROR_SUCCESS)
        goto _exit;

